import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import json
from datetime import datetime

# Read data
df = pd.read_csv('/app/benchmark/data.csv')

# Ensure correct data types
df['recorded_at'] = pd.to_datetime(df['recorded_at'])
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'])
df['price_pence'] = pd.to_numeric(df['price_pence'], errors='coerce')

# Drop missing prices
df = df.dropna(subset=['price_pence', 'recorded_at', 'source_updated_at', 'fuel_type'])

# Helper function to embed matplotlib figures as base64
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    data = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{data}"

# 1. Dataset Overview & Coverage Summary
total_records = len(df)
unique_stations = df['node_id'].nunique()
fuel_types = df['fuel_type'].unique().tolist()
date_min = df['recorded_at'].min().strftime('%Y-%m-%d')
date_max = df['recorded_at'].max().strftime('%Y-%m-%d')

# 2. Price Distribution by Fuel Type & Spread Analysis
stats_by_fuel = df.groupby('fuel_type')['price_pence'].agg(
    count='count',
    mean='mean',
    median='median',
    min='min',
    max='max',
    std='std'
).reset_index()

stats_by_fuel['iqr'] = df.groupby('fuel_type')['price_pence'].apply(lambda x: x.quantile(0.75) - x.quantile(0.25)).values
stats_by_fuel['spread'] = stats_by_fuel['max'] - stats_by_fuel['min']

# Chart: Boxplot of Price Distribution
sns.set_theme(style="whitegrid")
fig_box, ax_box = plt.subplots(figsize=(10, 6))
sns.boxplot(x='fuel_type', y='price_pence', data=df, ax=ax_box, palette="Set2")
ax_box.set_title('Price Distribution by Fuel Type', fontsize=14)
ax_box.set_xlabel('Fuel Type', fontsize=12)
ax_box.set_ylabel('Price (pence per litre)', fontsize=12)
img_box = fig_to_base64(fig_box)

# 3. Retailer Reporting Freshness Analysis
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600.0
# Negative lag implies issue, handle safely
median_lag_overall = df['update_lag_hours'].median()

fig_lag, ax_lag = plt.subplots(figsize=(10, 6))
sns.histplot(df['update_lag_hours'].clip(lower=0, upper=df['update_lag_hours'].quantile(0.95)), bins=50, ax=ax_lag, color='skyblue')
ax_lag.set_title('Distribution of Update Lag (Clipped to 95th Percentile)', fontsize=14)
ax_lag.set_xlabel('Lag (Hours)', fontsize=12)
ax_lag.set_ylabel('Frequency', fontsize=12)
img_lag = fig_to_base64(fig_lag)

# 4. Station Coverage & Fuel Type Availability
station_fuel_counts = df.groupby('node_id')['fuel_type'].nunique()
avg_fuels_per_station = station_fuel_counts.mean()

fig_coverage, ax_coverage = plt.subplots(figsize=(8, 5))
station_fuel_counts.value_counts().sort_index().plot(kind='bar', color='coral', ax=ax_coverage)
ax_coverage.set_title('Number of Fuel Types Reported per Station', fontsize=14)
ax_coverage.set_xlabel('Number of Fuel Types', fontsize=12)
ax_coverage.set_ylabel('Number of Stations', fontsize=12)
ax_coverage.tick_params(axis='x', rotation=0)
img_coverage = fig_to_base64(fig_coverage)

# KPIs
kpi_avg_prices = {row['fuel_type']: round(row['mean'], 2) for _, row in stats_by_fuel.iterrows()}
kpi_spreads = {row['fuel_type']: round(row['spread'], 2) for _, row in stats_by_fuel.iterrows()}
kpi_iqrs = {row['fuel_type']: round(row['iqr'], 2) for _, row in stats_by_fuel.iterrows()}

html = f"""
<!DOCTYPE html>
<html lang="en">
<head>
