            margin-top: 10px;
        }}
    </style>
</head>
<body>

    <div class="header">
        <h1>UK Retail Fuel Price Trend Analysis</h1>
        <p><strong>Audience:</strong> Government Policy Analysts & Energy Economists</p>
        <p><strong>Date Range:</strong> {date_min} to {date_max}</p>
    </div>

    <div class="section" id="overview">
        <h2>Dataset Overview & Coverage Summary</h2>
        <div class="kpi-container">
